class Solution:

	def IsPrime(self, num):
		i = 2
		while i * i < num:
			if num % i == 0:
				return False
			i = i + 1
		if i * i == num:
			return False
		return True

	def solve(self, Num1, Num2):
		FourDigitPrimes = {}
		for number in range(1000, 10000):
			if self.IsPrime(number):
				FourDigitPrimes[number] = 0
		from collections import deque
		Queue = deque()
		Queue.append([Num1, 0])
		FourDigitPrimes[Num1] = 1
		while len(Queue) != 0:
			top = Queue.popleft()
			(num, step) = (str(top[0]), top[1])
			if int(num) == Num2:
				return step
			for place in range(0, len(num)):
				temp = num[place]
				for digit in range(0, 10):
					num = num[:place] + str(digit) + num[place + 1:]
					if int(num) in FourDigitPrimes and FourDigitPrimes[int(num)] == 0:
						FourDigitPrimes[int(num)] = 1
						Queue.append([int(num), step + 1])
				num = num[:place] + str(temp) + num[place + 1:]
		return step
